"""Tests for tasks_api.queries — TaskQuery validation and apply_query."""

from __future__ import annotations

from datetime import datetime, timedelta, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.queries import TaskPage, TaskQuery, TaskQueryError, apply_query
from tests.conftest import FIXED_NOW, make_task


# ── TaskQuery validation ────────────────────────────────────────────

class TestTaskQueryValidation:
    def test_defaults(self):
        q = TaskQuery()
        assert q.sort == "created_at"
        assert q.limit == 20
        assert q.offset == 0
        assert q.descending is False

    @pytest.mark.parametrize("field", ["created_at", "due_at", "priority", "title"])
    def test_valid_sort_fields(self, field):
        q = TaskQuery(sort=field)
        assert q.sort == field

    def test_invalid_sort_raises(self):
        with pytest.raises(TaskQueryError, match="sort must be one of"):
            TaskQuery(sort="invalid")

    @pytest.mark.parametrize("limit", [0, -1, 101, "abc"])
    def test_invalid_limit_raises(self, limit):
        with pytest.raises(TaskQueryError, match="limit"):
            TaskQuery(limit=limit)

    def test_negative_offset_raises(self):
        with pytest.raises(TaskQueryError):
            TaskQuery(offset=-1)

    def test_tag_is_normalized(self):
        q = TaskQuery(tag="  MyTag  ")
        assert q.tag == "mytag"

    def test_invalid_tag_raises(self):
        with pytest.raises(ValueError):
            TaskQuery(tag="invalid tag!")

    def test_whitespace_search_becomes_none(self):
        q = TaskQuery(search="   ")
        assert q.search is None

    def test_search_is_stripped(self):
        q = TaskQuery(search="  hello  ")
        assert q.search == "hello"


# ── TaskPage ────────────────────────────────────────────────────────

class TestTaskPage:
    def test_has_more_true(self):
        page = TaskPage(items=[make_task()], total=5, limit=2, offset=0)
        assert page.has_more is True

    def test_has_more_false_at_end(self):
        items = [make_task(id=i) for i in range(3)]
        page = TaskPage(items=items, total=3, limit=10, offset=0)
        assert page.has_more is False

    def test_has_more_with_offset(self):
        page = TaskPage(items=[make_task()], total=3, limit=2, offset=2)
        assert page.has_more is False


# ── apply_query filtering ──────────────────────────────────────────

class TestApplyQueryFiltering:
    @pytest.fixture
    def sample_tasks(self):
        past = FIXED_NOW - timedelta(days=1)
        future = FIXED_NOW + timedelta(days=1)
        return [
            make_task(id=1, title="Buy groceries", status=TaskStatus.PENDING,
                      priority=TaskPriority.HIGH, due_at=past, tags=[Tag("shopping")]),
            make_task(id=2, title="Write report", status=TaskStatus.DONE,
                      priority=TaskPriority.MEDIUM, due_at=future, tags=[Tag("work")]),
            make_task(id=3, title="Call dentist", status=TaskStatus.PENDING,
                      priority=TaskPriority.LOW, tags=[Tag("health"), Tag("shopping")]),
        ]

    def test_no_filter_returns_all(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(), FIXED_NOW)
        assert page.total == 3

    def test_filter_by_status_pending(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(status=TaskStatus.PENDING), FIXED_NOW)
        assert page.total == 2
        assert all(t.status == TaskStatus.PENDING for t in page.items)

    def test_filter_by_status_done(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(status=TaskStatus.DONE), FIXED_NOW)
        assert page.total == 1
        assert page.items[0].id == 2

    def test_filter_by_tag(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(tag="shopping"), FIXED_NOW)
        assert page.total == 2
        assert {t.id for t in page.items} == {1, 3}

    def test_filter_by_search(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(search="report"), FIXED_NOW)
        assert page.total == 1
        assert page.items[0].title == "Write report"

    def test_search_case_insensitive(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(search="BUY"), FIXED_NOW)
        assert page.total == 1

    def test_filter_overdue_true(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(overdue=True), FIXED_NOW)
        assert page.total == 1
        assert page.items[0].id == 1

    def test_filter_overdue_false(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(overdue=False), FIXED_NOW)
        assert page.total == 2
        ids = {t.id for t in page.items}
        assert ids == {2, 3}


# ── apply_query sorting ────────────────────────────────────────────

class TestApplyQuerySorting:
    @pytest.fixture
    def tasks_for_sort(self):
        base = FIXED_NOW
        return [
            make_task(id=1, title="Banana", priority=TaskPriority.LOW,
                      created_at=base - timedelta(hours=2),
                      due_at=base + timedelta(days=3)),
            make_task(id=2, title="Apple", priority=TaskPriority.HIGH,
                      created_at=base - timedelta(hours=1),
                      due_at=base + timedelta(days=1)),
            make_task(id=3, title="Cherry", priority=TaskPriority.MEDIUM,
                      created_at=base, due_at=None),
        ]

    def test_sort_by_created_at_asc(self, tasks_for_sort):
        page = apply_query(tasks_for_sort, TaskQuery(sort="created_at"), FIXED_NOW)
        assert [t.id for t in page.items] == [1, 2, 3]

    def test_sort_by_created_at_desc(self, tasks_for_sort):
        page = apply_query(tasks_for_sort, TaskQuery(sort="created_at", descending=True), FIXED_NOW)
        assert [t.id for t in page.items] == [3, 2, 1]

    def test_sort_by_title(self, tasks_for_sort):
        page = apply_query(tasks_for_sort, TaskQuery(sort="title"), FIXED_NOW)
        assert [t.title for t in page.items] == ["Apple", "Banana", "Cherry"]

    def test_sort_by_priority(self, tasks_for_sort):
        page = apply_query(tasks_for_sort, TaskQuery(sort="priority"), FIXED_NOW)
        # HIGH first (order_key=0), then MEDIUM (1), then LOW (2)
        assert [t.priority for t in page.items] == [
            TaskPriority.HIGH, TaskPriority.MEDIUM, TaskPriority.LOW
        ]

    def test_sort_by_due_at_none_sorts_last(self, tasks_for_sort):
        page = apply_query(tasks_for_sort, TaskQuery(sort="due_at"), FIXED_NOW)
        assert page.items[-1].due_at is None
        assert page.items[0].due_at is not None


# ── apply_query pagination ──────────────────────────────────────────

class TestApplyQueryPagination:
    @pytest.fixture
    def many_tasks(self):
        return [make_task(id=i, title=f"Task {i}") for i in range(1, 11)]

    def test_limit(self, many_tasks):
        page = apply_query(many_tasks, TaskQuery(limit=3), FIXED_NOW)
        assert len(page.items) == 3
        assert page.total == 10
        assert page.has_more is True

    def test_offset(self, many_tasks):
        page = apply_query(many_tasks, TaskQuery(limit=3, offset=8), FIXED_NOW)
        assert len(page.items) == 2
        assert page.has_more is False

    def test_offset_beyond_total(self, many_tasks):
        page = apply_query(many_tasks, TaskQuery(offset=20), FIXED_NOW)
        assert len(page.items) == 0
        assert page.total == 10
        assert page.has_more is False

    def test_empty_input(self):
        page = apply_query([], TaskQuery(), FIXED_NOW)
        assert page.items == []
        assert page.total == 0
        assert page.has_more is False

